return (function validateInput() {
 const rows=$input.all();
 if(rows.length!==1)throw Error('Use one contact per lookup. Add a loop for a contact list.');
 const c={...rows[0].json};
 if(!/^[A-Za-z0-9._:-]{1,128}$/.test(c.idempotencyKey||'')||c.idempotencyKey==='REPLACE_WITH_STABLE_EVENT_ID')throw Error('Set idempotencyKey to a stable contact-event ID and keep it for retries.');
 if(typeof c.allowPaid!=='boolean'||typeof c.recoverOnly!=='boolean')throw Error('Set allowPaid and recoverOnly to true or false.');
 if(c.recoverOnly)return [{json:{config:c,recovering:true}}];
 const text=c.maxSpend;
 if(typeof text!=='string'||!/^(0|[1-9][0-9]{0,2})(\.[0-9]{1,6})?$/.test(text))throw Error('Set maxSpend to an amount such as "0.05".');
 const [whole,fraction='']=text.split('.'),limit=Number(whole)*1000000+Number(fraction.padEnd(6,'0'));
 if(limit>100000000||!['GBP','USD','EUR'].includes(c.currency))throw Error('Check maxSpend and your workspace currency.');
 if(typeof c.phone!=='string'||!c.phone.trim())throw Error('Enter the phone number to check.');
 if(c.defaultCountry&&!(typeof c.defaultCountry==='string'&&/^[A-Za-z]{2}$/.test(c.defaultCountry)))throw Error('Use a two-letter defaultCountry for local numbers.');
 const allowed=['basic_line_type','enhanced_line_type','current_carrier','mnp','live_status','sms','whatsapp','telegram'];
 if(!Array.isArray(c.checks)||!c.checks.length||new Set(c.checks).size!==c.checks.length||c.checks.some(v=>!allowed.includes(v)))throw Error('Select supported checks without duplicates.');
 if(c.checks.some(v=>v!=='basic_line_type')&&c.allowPaid!==true)throw Error('Paid use is off. Choose only basic_line_type or enable allowPaid after reviewing the price.');
 return [{json:{config:c,recovering:false,input:{phone:c.phone,...(c.defaultCountry?{defaultCountry:c.defaultCountry}:{}),checks:c.checks,currency:c.currency,maxSpend:c.maxSpend}}}];
})();

return (function recoveryResult() {
 const response=$input.first().json,c=$('Validate input').first().json.config;
 if(response.statusCode!==200||!['not_started','pending','settled','expired'].includes(response.body?.state))throw Error('Status unavailable. Keep the original idempotencyKey; no replacement lookup was run.');
 return [{json:{...response.body,idempotencyKey:c.idempotencyKey}}];
})();

return (function executionResult() {
 const response=$input.first().json,c=$('Validate input').first().json.config;
 if(response.statusCode!==200||!response.body?.number||typeof response.body?.billing?.amount!=='string')throw Error((response.body?.error?.code||'LOOKUP_UNRESOLVED')+' — keep idempotencyKey='+c.idempotencyKey+' and set recoverOnly=true to read its status. Do not create a replacement lookup.');
 return [{json:{state:'settled',idempotencyKey:c.idempotencyKey,result:response.body}}];
})();

return (function contactFields() {
 const r=$input.first().json;
 if(r.state!=='settled'||!r.result)return [{json:r}];
 const result=r.result,tri=value=>typeof value==='boolean'?value:null;
 return [{json:{...r,contactUpdate:{phone:result.number.e164,number_type:result.number.type??null,carrier:result.number.carrier??null,ported:tri(result.number.ported),sms_supported:tri(result.contact?.sms?.supported),sms_assumed:result.contact?.sms?.assumed??false,whatsapp_registered:tri(result.contact?.whatsapp?.registered),telegram_registered:tri(result.contact?.telegram?.registered),network_reachable:tri(result.network?.reachable),sms_reason:result.contact?.sms?.reason??null,whatsapp_reason:result.contact?.whatsapp?.reason??null,telegram_reason:result.contact?.telegram?.reason??null,network_reason:result.network?.reason??null,request_id:result.requestId,currency:result.billing?.currency??null,charged_amount:result.billing?.amount??null}}}];
})();
